/**
 * Sheet FSM - Finite State Machine for Sheet visibility and animation
 *
 * This FSM models the visibility lifecycle of a Sheet component,
 * including animation states for smooth open/close transitions.
 *
 * States:
 * - closed: Sheet is not rendered, not visible
 * - opening: Sheet is rendering, playing enter animation (slide-in)
 * - open: Sheet is fully visible and interactive
 * - closing: Sheet is playing exit animation (slide-out)
 *
 * Events:
 * - OPEN: Request to open the sheet
 * - CLOSE: Request to close the sheet (user action: ESC, backdrop click, close button)
 * - ANIMATION_END: Animation has completed
 *
 * This FSM enables:
 * - Smooth slide animations between states
 * - Proper focus management during transitions
 * - Preventing close during opening animation (and vice versa)
 * - Deterministic, testable state transitions
 *
 * @packageDocumentation
 */

/**
 * Visibility states for the Sheet FSM
 */
export type SheetVisibilityState = 'closed' | 'opening' | 'open' | 'closing';

/**
 * The Sheet FSM state object
 */
export interface SheetFSMState {
  /**
   * Current visibility/animation state
   */
  readonly visibility: SheetVisibilityState;

  /**
   * Whether the sheet should be rendered in DOM
   * True for: opening, open, closing
   * False for: closed
   */
  readonly shouldRender: boolean;

  /**
   * Whether the sheet should have the 'show' class for CSS animations
   * True for: open
   * False for: opening, closing, closed
   */
  readonly shouldShow: boolean;

  /**
   * Whether focus trap should be active
   * True for: open
   * False for: opening, closing, closed
   */
  readonly focusTrapActive: boolean;

  /**
   * Whether scroll lock should be active
   * True for: opening, open, closing
   * False for: closed
   */
  readonly scrollLockActive: boolean;
}

/**
 * Events that trigger state transitions in the Sheet FSM
 */
export type SheetFSMEvent =
  | { readonly type: 'OPEN' }
  | { readonly type: 'CLOSE' }
  | { readonly type: 'ANIMATION_END' };

/**
 * Creates the initial FSM state based on the isOpen prop
 *
 * @param isOpen - Whether the sheet should initially be open
 * @returns The initial FSM state
 */
export function createInitialSheetFSMState(isOpen: boolean): SheetFSMState {
  if (isOpen) {
    // If initially open, skip opening animation and go straight to open
    return {
      visibility: 'open',
      shouldRender: true,
      shouldShow: true,
      focusTrapActive: true,
      scrollLockActive: true,
    };
  }

  return {
    visibility: 'closed',
    shouldRender: false,
    shouldShow: false,
    focusTrapActive: false,
    scrollLockActive: false,
  };
}

/**
 * Pure reducer function for the Sheet FSM
 *
 * State Transition Table:
 *
 * | Current State | Event          | Next State | shouldRender | shouldShow | focusTrap | scrollLock |
 * |---------------|----------------|------------|--------------|------------|-----------|------------|
 * | closed        | OPEN           | opening    | true         | false      | false     | true       |
 * | closed        | CLOSE          | closed     | false        | false      | false     | false      |
 * | closed        | ANIMATION_END  | closed     | false        | false      | false     | false      |
 * | opening       | OPEN           | opening    | true         | false      | false     | true       |
 * | opening       | CLOSE          | closing    | true         | false      | false     | true       |
 * | opening       | ANIMATION_END  | open       | true         | true       | true      | true       |
 * | open          | OPEN           | open       | true         | true       | true      | true       |
 * | open          | CLOSE          | closing    | true         | false      | false     | true       |
 * | open          | ANIMATION_END  | open       | true         | true       | true      | true       |
 * | closing       | OPEN           | opening    | true         | false      | false     | true       |
 * | closing       | CLOSE          | closing    | true         | false      | false     | true       |
 * | closing       | ANIMATION_END  | closed     | false        | false      | false     | false      |
 *
 * @param state - Current FSM state
 * @param event - Event triggering the transition
 * @returns New FSM state
 */
export function sheetFSMReducer(state: SheetFSMState, event: SheetFSMEvent): SheetFSMState {
  switch (state.visibility) {
    case 'closed':
      switch (event.type) {
        case 'OPEN':
          return {
            visibility: 'opening',
            shouldRender: true,
            shouldShow: false,
            focusTrapActive: false,
            scrollLockActive: true,
          };
        case 'CLOSE':
        case 'ANIMATION_END':
          // Already closed, stay closed (idempotent)
          return state;
        default:
          return state;
      }

    case 'opening':
      switch (event.type) {
        case 'OPEN':
          // Already opening, stay opening (idempotent)
          return state;
        case 'CLOSE':
          // User requested close during opening, go to closing
          return {
            visibility: 'closing',
            shouldRender: true,
            shouldShow: false,
            focusTrapActive: false,
            scrollLockActive: true,
          };
        case 'ANIMATION_END':
          // Opening animation finished, now fully open
          return {
            visibility: 'open',
            shouldRender: true,
            shouldShow: true,
            focusTrapActive: true,
            scrollLockActive: true,
          };
        default:
          return state;
      }

    case 'open':
      switch (event.type) {
        case 'OPEN':
        case 'ANIMATION_END':
          // Already open, stay open (idempotent)
          return state;
        case 'CLOSE':
          // User requested close
          return {
            visibility: 'closing',
            shouldRender: true,
            shouldShow: false,
            focusTrapActive: false,
            scrollLockActive: true,
          };
        default:
          return state;
      }

    case 'closing':
      switch (event.type) {
        case 'OPEN':
          // User requested open during closing, go back to opening
          return {
            visibility: 'opening',
            shouldRender: true,
            shouldShow: false,
            focusTrapActive: false,
            scrollLockActive: true,
          };
        case 'CLOSE':
          // Already closing, stay closing (idempotent)
          return state;
        case 'ANIMATION_END':
          // Closing animation finished, now fully closed
          return {
            visibility: 'closed',
            shouldRender: false,
            shouldShow: false,
            focusTrapActive: false,
            scrollLockActive: false,
          };
        default:
          return state;
      }

    default:
      return state;
  }
}

/**
 * Compute the data-visual-state attribute value from FSM state
 *
 * @param state - Current FSM state
 * @returns String for data-visual-state attribute
 */
export function getSheetVisualState(state: SheetFSMState): string {
  return state.visibility;
}

import React, {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';
import { createPortal } from 'react-dom';

import { useFocusTrap } from '../../hooks/useFocusTrap';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import { useScrollLock } from '../../hooks/useScrollLock';
import { cn, isBrowser, mergeRefs } from '../../utils';
import { isEscapeKey } from '../../utils/keyboard';
import { Heading } from '../Typography';

import { createInitialSheetFSMState, getSheetVisualState, sheetFSMReducer } from './Sheet.fsm';

import type {
  SheetBodyProps,
  SheetContextValue,
  SheetFooterProps,
  SheetHeaderProps,
  SheetPlacement,
  SheetProps,
  SheetTitleProps,
} from './Sheet.types';

// ============================================================================
// Sheet Context
// ============================================================================

const SheetContext = createContext<SheetContextValue | null>(null);

/**
 * Hook to access Sheet context
 * @throws Error if used outside of Sheet
 */
function useSheetContext(): SheetContextValue {
  const context = useContext(SheetContext);
  if (!context) {
    throw new Error('Sheet compound components must be used within a Sheet');
  }
  return context;
}

// ============================================================================
// Sheet.Title Component
// ============================================================================

const SheetTitle = React.memo(function SheetTitle({
  children,
  as: Component = 'h5',
  className = '',
  id,
}: SheetTitleProps): React.JSX.Element {
  const context = useSheetContext();
  const titleId = id ?? context.titleId;

  const classes = useMemo(() => cn('offcanvas-title', className), [className]);

  return (
    <Component id={titleId} className={classes}>
      {children}
    </Component>
  );
});

SheetTitle.displayName = 'Sheet.Title';

// ============================================================================
// Sheet.Header Component
// ============================================================================

const SheetHeader = React.memo(
  forwardRef<HTMLDivElement, SheetHeaderProps>(function SheetHeader(
    {
      children,
      closeButton = true,
      onClose,
      className = '',
      style,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) {
    const context = useSheetContext();
    const handleClose = onClose ?? context.onClose;

    const classes = useMemo(() => cn('offcanvas-header', className), [className]);

    // Determine if children is a string (needs wrapping in Sheet.Title)
    const isStringChild = typeof children === 'string';

    return (
      <div
        ref={ref}
        className={classes}
        style={style}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {isStringChild ? (
          <Heading level={5} id={context.titleId} className="offcanvas-title">
            {children}
          </Heading>
        ) : (
          children
        )}
        {closeButton && (
          <button
            type="button"
            className="btn-close"
            aria-label="Close"
            onClick={() => handleClose?.()}
          />
        )}
      </div>
    );
  })
);

SheetHeader.displayName = 'Sheet.Header';

// ============================================================================
// Sheet.Body Component
// ============================================================================

const SheetBody = React.memo(
  forwardRef<HTMLDivElement, SheetBodyProps>(function SheetBody(
    { children, className = '', style, 'data-testid': dataTestId, 'data-test': dataTest },
    ref
  ) {
    const context = useSheetContext();

    // flex-grow-1 ensures body takes remaining space, pushing footer to bottom
    const classes = useMemo(() => cn('offcanvas-body', 'flex-grow-1', className), [className]);

    return (
      <div
        ref={ref}
        id={context.bodyId}
        className={classes}
        style={style}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {children}
      </div>
    );
  })
);

SheetBody.displayName = 'Sheet.Body';

// ============================================================================
// Sheet.Footer Component
// ============================================================================

const SheetFooter = React.memo(
  forwardRef<HTMLDivElement, SheetFooterProps>(function SheetFooter(
    { children, className = '', style, 'data-testid': dataTestId, 'data-test': dataTest },
    ref
  ) {
    // Use modal-footer for styling + mt-auto to push footer to bottom of sheet
    // flex-shrink-0 prevents footer from shrinking when body has overflow
    // border-top adds visual separator, p-3 adds consistent padding
    // gap-3 adds 16px spacing between children, justify-content-between spreads them
    const classes = useMemo(
      () =>
        cn(
          'modal-footer',
          'mt-auto',
          'p-3',
          'gap-3',
          'flex-shrink-0',
          'border-top',
          'justify-content-between',
          className
        ),
      [className]
    );

    return (
      <div
        ref={ref}
        className={classes}
        style={style}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {children}
      </div>
    );
  })
);

SheetFooter.displayName = 'Sheet.Footer';

// ============================================================================
// Size Constants
// ============================================================================

/**
 * Size values in pixels for each size variant
 * Used for left/right (width) and top/bottom (height) placements
 */
const SIZE_VALUES = new Map<string, string>([
  ['sm', '320px'],
  ['md', '400px'],
  ['lg', '540px'],
  ['xl', '720px'],
  ['full', '100%'],
  ['auto', 'auto'],
]);

const DEFAULT_SIZE = '400px';

/**
 * Get CSS dimension value based on size and custom dimension
 */
function getDimensionValue(size: string, customDimension: string | number | undefined): string {
  if (customDimension !== undefined) {
    return typeof customDimension === 'number' ? `${customDimension}px` : customDimension;
  }
  return SIZE_VALUES.get(size) ?? DEFAULT_SIZE;
}

/**
 * Map placement to Bootstrap Offcanvas class suffix
 * Bootstrap uses RTL-aware naming: left→start, right→end
 */
function getPlacementClass(placement: SheetPlacement): string {
  switch (placement) {
    case 'left':
      return 'offcanvas-start';
    case 'right':
      return 'offcanvas-end';
    case 'top':
      return 'offcanvas-top';
    case 'bottom':
      return 'offcanvas-bottom';
    default:
      return 'offcanvas-end';
  }
}

// ============================================================================
// Sheet Component
// ============================================================================

/**
 * Sheet Component
 *
 * An accessible slide-out panel component for navigation, forms, and secondary content.
 * Supports all four placement positions (left, right, top, bottom) with smooth animations.
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted prop spreading)
 * - Explicit event handlers only
 * - No dangerouslySetInnerHTML
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="dialog" for screen readers
 * - aria-modal="true" to indicate modal context
 * - aria-labelledby pointing to header
 * - aria-describedby pointing to body
 * - Focus trap within sheet (Tab cycles within sheet)
 * - Focus first focusable element on open
 * - Restore focus to trigger on close
 * - ESC key to close
 * - Body scroll lock when open
 *
 * PERFORMANCE FEATURES:
 * - Memoized subcomponents
 * - Memoized class name construction
 * - FSM for predictable state management
 * - Portal rendering for z-index isolation
 * - GPU-accelerated transform animations
 *
 * @example
 * ```tsx
 * const [isOpen, setIsOpen] = useState(false);
 *
 * <Button onClick={() => setIsOpen(true)}>Open Sheet</Button>
 *
 * <Sheet isOpen={isOpen} onClose={() => setIsOpen(false)} placement="right">
 *   <Sheet.Header>Settings</Sheet.Header>
 *   <Sheet.Body>
 *     <p>Sheet content goes here.</p>
 *   </Sheet.Body>
 *   <Sheet.Footer>
 *     <Button variant="secondary" onClick={() => setIsOpen(false)}>
 *       Cancel
 *     </Button>
 *     <Button variant="primary" onClick={handleSave}>
 *       Save
 *     </Button>
 *   </Sheet.Footer>
 * </Sheet>
 * ```
 */
const SheetBase = forwardRef<HTMLDivElement, SheetProps>(
  (
    {
      children,
      isOpen,
      onClose,
      placement = 'right',
      size = 'md',
      surface = 'default',
      mode = 'modal',
      closeOnBackdropClick = true,
      closeOnEscape = true,
      backdrop = true,
      staticBackdrop = false,
      titleId: titleIdProp,
      bodyId: bodyIdProp,
      container,
      onOpened,
      onClosed,
      initialFocusRef,
      returnFocusRef,
      zIndex = 1055,
      animated = true,
      // API compatibility: `scrollable` is accepted but unused because Bootstrap's
      // offcanvas-body handles scrolling natively via overflow-y: auto.
      scrollable: _scrollable = true,
      width,
      height,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    // Generate unique IDs for accessibility
    const generatedId = useId();
    const titleId = titleIdProp ?? `sheet-title-${generatedId}`;
    const bodyId = bodyIdProp ?? `sheet-body-${generatedId}`;

    // Internal ref for the offcanvas element (used for focus trap and animations)
    const sheetRef = useRef<HTMLDivElement>(null);

    // Determine if this is a modal sheet (needs scroll lock and focus trap)
    const isModalMode = mode === 'modal';

    // Respect user's reduced motion preference (WCAG 2.2 AA compliance)
    const prefersReducedMotion = useReducedMotion();
    const shouldAnimate = animated && !prefersReducedMotion;

    // Initialize FSM
    const [fsmState, dispatch] = useReducer(sheetFSMReducer, isOpen, createInitialSheetFSMState);

    // Local state to trigger CSS transition for animated sheets
    const [animatedShowClass, setAnimatedShowClass] = useState(() => isOpen && shouldAnimate);

    // For non-animated sheets, derive showClass directly from FSM state
    const showClass = shouldAnimate
      ? fsmState.visibility === 'closing' || fsmState.visibility === 'closed'
        ? false
        : animatedShowClass
      : fsmState.visibility === 'opening' || fsmState.visibility === 'open';

    // Handle adding 'show' class after repaint for CSS transitions
    useEffect(() => {
      if (!shouldAnimate) {
        return undefined;
      }

      if (fsmState.visibility === 'opening' && !animatedShowClass) {
        let innerFrameId: number | undefined;
        const frameId = requestAnimationFrame(() => {
          innerFrameId = requestAnimationFrame(() => {
            setAnimatedShowClass(true);
          });
        });
        return () => {
          cancelAnimationFrame(frameId);
          if (innerFrameId !== undefined) {
            cancelAnimationFrame(innerFrameId);
          }
        };
      }

      if (fsmState.visibility === 'closed' && animatedShowClass) {
        const timeoutId = setTimeout(() => {
          setAnimatedShowClass(false);
        }, 0);
        return () => clearTimeout(timeoutId);
      }

      return undefined;
    }, [shouldAnimate, fsmState.visibility, animatedShowClass]);

    // Sync FSM with isOpen prop
    useEffect(() => {
      if (isOpen && fsmState.visibility === 'closed') {
        dispatch({ type: 'OPEN' });
      } else if (!isOpen && (fsmState.visibility === 'open' || fsmState.visibility === 'opening')) {
        dispatch({ type: 'CLOSE' });
      }
    }, [isOpen, fsmState.visibility]);

    // Focus trap - only for modal mode
    useFocusTrap({
      enabled: isModalMode && fsmState.focusTrapActive,
      containerRef: sheetRef,
      initialFocusRef,
      finalFocusRef: returnFocusRef,
      initialFocusDelay: 50,
    });

    // Scroll lock - only for modal mode
    useScrollLock({ enabled: isModalMode && fsmState.scrollLockActive });

    // Handle ESC key
    useEffect(() => {
      if (!closeOnEscape || fsmState.visibility !== 'open') {
        return;
      }

      const handleKeyDown = (event: KeyboardEvent): void => {
        if (isEscapeKey(event)) {
          event.preventDefault();
          onClose();
        }
      };

      document.addEventListener('keydown', handleKeyDown);
      return () => document.removeEventListener('keydown', handleKeyDown);
    }, [closeOnEscape, fsmState.visibility, onClose]);

    // Handle backdrop click
    const handleBackdropClick = useCallback(() => {
      if (staticBackdrop) {
        // Bootstrap Modal uses 'modal-static' for the shake effect
        // Offcanvas doesn't have this built-in, but consuming apps can style it
        sheetRef.current?.classList.add('offcanvas-static');
        setTimeout(() => {
          sheetRef.current?.classList.remove('offcanvas-static');
        }, 300);
        return;
      }

      if (closeOnBackdropClick && isModalMode) {
        onClose();
      }
    }, [closeOnBackdropClick, staticBackdrop, isModalMode, onClose]);

    // Handle animation end
    const handleTransitionEnd = useCallback(
      (event: React.TransitionEvent<HTMLDivElement>) => {
        // Only respond to transform transitions on the offcanvas element
        if (event.propertyName !== 'transform' || event.target !== sheetRef.current) {
          return;
        }

        dispatch({ type: 'ANIMATION_END' });

        if (fsmState.visibility === 'opening') {
          onOpened?.();
        } else if (fsmState.visibility === 'closing') {
          onClosed?.();
        }
      },
      [fsmState.visibility, onOpened, onClosed]
    );

    // For non-animated sheets, trigger animation end immediately
    const prevVisibilityRef = useRef(fsmState.visibility);
    useEffect(() => {
      const prevVisibility = prevVisibilityRef.current;
      const currentVisibility = fsmState.visibility;
      prevVisibilityRef.current = currentVisibility;

      if (shouldAnimate) {
        return undefined;
      }

      if (currentVisibility === 'opening') {
        dispatch({ type: 'ANIMATION_END' });
        return undefined;
      }

      if (currentVisibility === 'closing') {
        dispatch({ type: 'ANIMATION_END' });
        return undefined;
      }

      if (prevVisibility === 'opening' && currentVisibility === 'open') {
        const timeoutId = setTimeout(() => {
          onOpened?.();
        }, 0);
        return () => clearTimeout(timeoutId);
      }

      if (prevVisibility === 'closing' && currentVisibility === 'closed') {
        const timeoutId = setTimeout(() => {
          onClosed?.();
        }, 0);
        return () => clearTimeout(timeoutId);
      }

      return undefined;
    }, [shouldAnimate, fsmState.visibility, onOpened, onClosed]);

    // Handle initial open state
    const initialOpenHandled = useRef(false);
    useEffect(() => {
      if (!shouldAnimate && fsmState.visibility === 'open' && !initialOpenHandled.current) {
        initialOpenHandled.current = true;
        const timeoutId = setTimeout(() => {
          onOpened?.();
        }, 0);
        return () => clearTimeout(timeoutId);
      }
      return undefined;
    }, [shouldAnimate, fsmState.visibility, onOpened]);

    // Compute offcanvas classes using Bootstrap's native Offcanvas classes
    const offcanvasClasses = useMemo(
      () =>
        cn(
          'offcanvas',
          getPlacementClass(placement),
          // Bootstrap transition states
          fsmState.visibility === 'opening' && 'showing',
          fsmState.visibility === 'closing' && 'hiding',
          showClass && 'show',
          // DSAi extensions for surface variants (consuming apps style via SCSS)
          surface !== 'default' && `offcanvas-${surface}`,
          className
        ),
      [placement, fsmState.visibility, showClass, surface, className]
    );

    // Compute offcanvas styles - Bootstrap uses CSS custom properties
    const isHorizontal = placement === 'left' || placement === 'right';
    const dimension = isHorizontal
      ? getDimensionValue(size, width)
      : getDimensionValue(size, height);

    const offcanvasStyles = useMemo(
      () => ({
        // Bootstrap uses --bs-offcanvas-width and --bs-offcanvas-height CSS vars
        ...(isHorizontal
          ? { '--bs-offcanvas-width': dimension }
          : { '--bs-offcanvas-height': dimension }),
        visibility: fsmState.shouldRender ? 'visible' : 'hidden',
        zIndex,
        ...style,
      }),
      [isHorizontal, dimension, fsmState.shouldRender, zIndex, style]
    ) as React.CSSProperties;

    // Compute backdrop styles
    const backdropStyles = useMemo(
      () => ({
        zIndex: zIndex - 1,
      }),
      [zIndex]
    );

    // Context value for subcomponents
    const contextValue = useMemo<SheetContextValue>(
      () => ({
        onClose,
        titleId,
        bodyId,
        placement,
      }),
      [onClose, titleId, bodyId, placement]
    );

    // Don't render anything if not needed
    if (!fsmState.shouldRender) {
      return null;
    }

    // Get portal container
    const portalContainer = container ?? (isBrowser() ? document.body : null);

    if (!portalContainer) {
      return null;
    }

    const sheetContent = (
      <SheetContext.Provider value={contextValue}>
        {/* Backdrop - using <div> with aria-hidden (matches Modal pattern) */}
        {isModalMode && backdrop && (
          <div
            className={cn('offcanvas-backdrop', shouldAnimate && 'fade', showClass && 'show')}
            style={backdropStyles}
            aria-hidden="true"
            onClick={handleBackdropClick}
          />
        )}

        {/* Offcanvas - using Bootstrap's native structure */}
        <div
          ref={mergeRefs(sheetRef, ref)}
          className={offcanvasClasses}
          style={offcanvasStyles}
          id={id}
          role="dialog"
          aria-modal={isModalMode ? 'true' : undefined}
          aria-labelledby={titleId}
          aria-describedby={bodyId}
          tabIndex={-1}
          data-testid={dataTestId}
          data-test={dataTest}
          data-visual-state={getSheetVisualState(fsmState)}
          data-placement={placement}
          onTransitionEnd={shouldAnimate ? handleTransitionEnd : undefined}
        >
          {children}
        </div>
      </SheetContext.Provider>
    );

    return createPortal(sheetContent, portalContainer);
  }
);

SheetBase.displayName = 'Sheet';

// Create compound component
type SheetComponent = typeof SheetBase & {
  Header: typeof SheetHeader;
  Title: typeof SheetTitle;
  Body: typeof SheetBody;
  Footer: typeof SheetFooter;
};

export const Sheet = SheetBase as SheetComponent;
Sheet.Header = SheetHeader;
Sheet.Title = SheetTitle;
Sheet.Body = SheetBody;
Sheet.Footer = SheetFooter;

import type { ComponentSize, SafeHTMLAttributes } from '../../types';
import type { ReactNode, RefObject } from 'react';

/**
 * Sheet placement variants
 * Determines which edge of the viewport the sheet slides in from
 */
export type SheetPlacement = 'left' | 'right' | 'top' | 'bottom';

/**
 * Sheet size variants
 * Controls the width (for left/right) or height (for top/bottom) of the sheet
 * - sm: 320px (typical mobile nav width)
 * - md: 400px (standard sheet width)
 * - lg: 540px (wider content)
 * - xl: 720px (extra wide)
 * - full: 100% of viewport dimension
 * - auto: fit content
 */
export type SheetSize = ComponentSize | 'xl' | 'full' | 'auto';

/**
 * Sheet surface variants
 * Controls the visual appearance of the sheet
 */
export type SheetSurface = 'default' | 'elevated' | 'inverse' | 'transparent';

/**
 * Sheet mode variants
 * - modal: with backdrop, blocking (default)
 * - non-modal: no backdrop, non-blocking (can interact with background)
 */
export type SheetMode = 'modal' | 'non-modal';

/**
 * Whitelisted HTML attributes for safe prop spreading in Sheet component
 * SECURITY: Restricts arbitrary props to prevent injection attacks
 * @see {@link SafeHTMLAttributes}
 */
export type SafeSheetHTMLAttributes = SafeHTMLAttributes<HTMLDivElement>;

/**
 * Sheet component props
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="dialog" for screen readers
 * - aria-modal="true" for blocking overlays
 * - aria-labelledby pointing to header
 * - aria-describedby pointing to body (optional)
